WITH latest AS (
  SELECT m.*
  FROM measurements m
  JOIN (
    SELECT session_id, MAX(recorded_at) AS max_rec
    FROM measurements
    GROUP BY session_id
  ) t ON m.session_id = t.session_id AND m.recorded_at = t.max_rec
)
SELECT COUNT(*) AS n FROM latest;

